def forward(self, input_ids, **kwargs):
    seq_len = input_ids.shape[-1]
    if seq_len > self.rbln_config.max_seq_len:
        raise ValueError(
            f"input length {seq_len} > max_seq_len "
            f"{self.rbln_config.max_seq_len}")
    return self.model[0](input_ids, **kwargs)

