class DecoderOnlyWrapper(nn.Module):
    def get_decoder_layers(self, model):
        return model.layers
class DecoderOnlyForCausalLMWrapper(DecoderOnlyWrapper):
    def get_decoder_layers(self, model):
        return model.model.layers

class DecoderOnlyWrapper(nn.Module):
    def __init__(self, model, rbln_config):
        self.is_causal_lm = getattr(model, "lm_head", None) is not None
    def get_decoder_layers(self, model):
        return model.model.layers if self.is_causal_lm else model.layers

